function usage(error) {
  if(error) console.log("Error: " + error + "\n");
  console.log(process.argv[1] + ":");
  console.log("\t-h");
  console.log("\t-n <node>");
  console.log("\t-c <config file>");
  console.log("\t-p <plugin file>");
